import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/useAuth";
import { useSubmitQuote, useApproveQuote, useSendQuote, useRespondQuote, useCloneQuote } from "@/hooks/useQuotes";
import { Quote } from "@/types/api";
import { downloadQuotePdf } from "@/lib/api";

interface QuoteActionsProps {
  quote: Quote;
  projectId: string;
  onQuoteUpdate?: () => void;
}

export function QuoteActions({ quote, projectId, onQuoteUpdate }: QuoteActionsProps) {
  const { user } = useAuth();
  const isAdmin = user?.role === "admin";

  const submitMutation = useSubmitQuote();
  const approveMutation = useApproveQuote();
  const sendMutation = useSendQuote();
  const respondMutation = useRespondQuote();
  const cloneMutation = useCloneQuote();

  return (
    <div className="flex flex-wrap gap-2">
      <Button variant="outline" size="sm" onClick={() => downloadQuotePdf(quote.id)}>
        Download PDF
      </Button>
      {quote.status === "draft" && (
        <Button size="sm" onClick={async () => { await submitMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={submitMutation.isPending}>
          Submit for Approval
        </Button>
      )}
      {quote.status === "pending_approval" && isAdmin && (
        <>
          <Button size="sm" onClick={async () => { await approveMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={approveMutation.isPending}>
            Approve
          </Button>
          <Button size="sm" variant="outline" onClick={async () => { await respondMutation.mutateAsync({ quoteId: quote.id, projectId, response: "rejected" }); onQuoteUpdate?.(); }} disabled={respondMutation.isPending}>
            Reject to Draft
          </Button>
        </>
      )}
      {quote.status === "approved" && (
        <Button size="sm" onClick={async () => { await sendMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={sendMutation.isPending}>
          Send to Client
        </Button>
      )}
      {quote.status === "sent" && (
        <>
          <Button size="sm" onClick={async () => { await respondMutation.mutateAsync({ quoteId: quote.id, projectId, response: "accepted" }); onQuoteUpdate?.(); }} disabled={respondMutation.isPending}>
            Accept
          </Button>
          <Button size="sm" variant="destructive" onClick={async () => { await respondMutation.mutateAsync({ quoteId: quote.id, projectId, response: "rejected" }); onQuoteUpdate?.(); }} disabled={respondMutation.isPending}>
            Reject
          </Button>
        </>
      )}
      {quote.status === "rejected" && (
        <Button size="sm" onClick={async () => { await cloneMutation.mutateAsync({ quoteId: quote.id, projectId }); onQuoteUpdate?.(); }} disabled={cloneMutation.isPending}>
          Clone to Draft
        </Button>
      )}
    </div>
  );
}
