```tsx
import { useQuery } from "@tanstack/react-query";
import { useQuote } from "@/hooks/useQuotes";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { QuoteActions } from "./QuoteActions";
import { QuoteStatus } from "@/types/api";

const STATUS_COLORS: Record<QuoteStatus, string> = {
  draft: "bg-gray-100 text-gray-800",
  pending_approval: "bg-yellow-100 text-yellow-800",
  approved: "bg-blue-100 text-blue-800",
  sent: "bg-purple-100 text-purple-800",
  accepted: "bg-green-100 text-green-800",
  rejected: "bg-red-100 text-red-800",
};

const STATUS_TIMELINE = ["draft", "pending_approval", "approved", "sent", "accepted"] as const;

interface QuoteDetailProps {
  quoteId: string;
  projectId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function QuoteDetail({ quoteId, projectId, open, onOpenChange }: QuoteDetailProps) {
  const { data: quote, isLoading, refetch } = useQuote(quoteId);

  if (!quote) return null;

  const currentIndex = STATUS_TIMELINE.indexOf(quote.status as typeof STATUS_TIMELINE[number]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3">
            Quote #{quote.version_number}
            <span className={`px-2 py-1 rounded text-xs font-medium ${STATUS_COLORS[quote.status]}`}>
              {quote.status.replace("_", " ")}
            </span>
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          <Card>
            <CardHeader><CardTitle>Status Timeline</CardTitle></CardHeader>
            <CardContent>
              <div className="flex items-center gap-2">
                {STATUS_TIMELINE.map((status, i) => (
                  <div key={status} className="flex items-center gap-2">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-medium ${i <= currentIndex ? "bg-green-600 text-white" : "bg-gray-200 text-gray-500"}`}>
                      {i + 1}
                    </div>
                    <span className="text-sm capitalize">{status.replace("_", " ")}</span>
                    {i < STATUS_TIMELINE.length - 1 && (
                      <div className={`w-8 h-0.5 ${i < currentIndex ? "bg-green-600" : "bg-gray-200"}`} />
                    )}
                  </div>
                ))}
                {quote.status === "rejected" && (
                  <div className="ml-2 px-2 py-1 rounded text-xs font-medium bg-red-100 text-red-800">Rejected</div>
                )}
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader><CardTitle>Totals</CardTitle></CardHeader>
            <CardContent className="space-y-2">
              <div className="flex justify-between"><span>Subtotal</span><span>₹{quote.subtotal.toLocaleString()}</span></div>
              <div className="flex justify-between"><span>Markup ({quote.markup_percent}%)</span><span>₹{quote.markup_amount.toLocaleString()}</span></div>
              <div className="flex justify-between"><span>Tax ({quote.tax_percent}%)</span><span>₹{quote.tax_amount.toLocaleString()}</span></div>
              <div className="flex justify-between font-bold text-lg border-t pt-2"><span>Total</span><span>₹{quote.total_amount.toLocaleString()}</span></div>
              {quote.valid_until && <div className="mt-4 text-sm text-muted-foreground">Valid until: {new Date(quote.valid_until).toLocaleDateString()}</div>}
            </CardContent>
          </Card>

          {quote.terms && (
            <Card>
              <CardHeader><CardTitle>Terms & Conditions</CardTitle></CardHeader>
              <CardContent><p className="text-sm whitespace-pre-wrap">{quote.terms}</p></CardContent>
            </Card>
          )}

          <Card>
            <CardHeader><CardTitle>Quote Actions</CardTitle></CardHeader>
            <CardContent><QuoteActions quote={quote} projectId={projectId} onQuoteUpdate={refetch} /></CardContent>
          </Card>
        </div>
      </DialogContent>
    </Dialog>
  );
}
