input.newString:
deleteBOQ: (projectId: string, boqId: string) =>
    request<void>(`/api/projects/${projectId}/boqs/${boqId}`, { method: "DELETE" }),

  listQuotes: (projectId: string, params?: { page?: number; page_size?: number }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    const query = searchParams.toString();
    return request<QuoteListResponse>(`/api/projects/${projectId}/quotes${query ? `?${query}` : ""}`);
  },

  getQuote: (quoteId: string) => request<Quote>(`/api/quotes/${quoteId}`),

  createQuote: (projectId: string, data: { boq_id: string; markup_percent?: number; tax_percent?: number; terms?: string; validity_days?: number }) =>
    request<Quote>(`/api/projects/${projectId}/quotes`, {
      method: "POST",
      body: JSON.stringify(data),
    }),

  updateQuote: (quoteId: string, data: Partial<Quote>) =>
    request<Quote>(`/api/quotes/${quoteId}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  deleteQuote: (quoteId: string) =>
    request<void>(`/api/quotes/${quoteId}`, { method: "DELETE" }),

  submitQuote: (quoteId: string) =>
    request<Quote>(`/api/quotes/${quoteId}/submit`, { method: "POST" }),

  approveQuote: (quoteId: string) =>
    request<Quote>(`/api/quotes/${quoteId}/approve`, { method: "POST" }),

  sendQuote: (quoteId: string) =>
    request<Quote>(`/api/quotes/${quoteId}/send`, { method: "POST" }),

  respondQuote: (quoteId: string, data: { response: "accepted" | "rejected"; notes?: string }) =>
    request<Quote>(`/api/quotes/${quoteId}/respond`, {
      method: "POST",
      body: JSON.stringify(data),
    }),

  cloneQuote: (quoteId: string) =>
    request<Quote>(`/api/quotes/${quoteId}/clone`, { method: "POST" }),

  downloadQuotePdf: (quoteId: string) => {
    const token = getAccessToken();
    window.open(`/api/quotes/${quoteId}/pdf?token=${token}`, "_blank");
  },
};

export { ApiError };

export const listQuotes = (projectId: string, params?: { page?: number; page_size?: number }) =>
  api.listQuotes(projectId, params);

export const getQuote = (quoteId: string) => api.getQuote(quoteId);

export const createQuote = (projectId: string, data: { boq_id: string; markup_percent?: number; tax_percent?: number; terms?: string; validity_days?: number }) =>
  api.createQuote(projectId, data);

export const updateQuote = (quoteId: string, data: Partial<Quote>) =>
  api.updateQuote(quoteId, data);

export const deleteQuote = (quoteId: string) => api.deleteQuote(quoteId);

export const submitQuote = (quoteId: string) => api.submitQuote(quoteId);

export const approveQuote = (quoteId: string) => api.approveQuote(quoteId);

export const sendQuote = (quoteId: string) => api.sendQuote(quoteId);

export const respondQuote = (quoteId: string, data: { response: "accepted" | "rejected"; notes?: string }) =>
  api.respondQuote(quoteId, data);

export const cloneQuote = (quoteId: string) => api.cloneQuote(quoteId);

export const downloadQuotePdf = (quoteId: string) => api.downloadQuotePdf(quoteId);

export const getBoqItems = (boqId: string) => {
  const token = getAccessToken();
  const headers: Record<string, string> = {};
  if (token) headers["Authorization"] = `Bearer ${token}`;
  return fetch(`/api/boqs/${boqId}/items`, { headers }).then((r) => r.json()) as Promise<BOQItemListResponse>;
};

export const deleteBoq = (boqId: string) => api.deleteBOQ("", boqId);

export const uploadBoq = async ({ projectId, file, notes }: { projectId: string; file: File; notes?: string }) => {
  const token = getAccessToken();
  const formData = new FormData();
  formData.append("file", file);
  if (notes) formData.append("notes", notes);
  const response = await fetch(`/api/projects/${projectId}/boqs`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}` },
    body: formData,
  });
  if (!response.ok) throw new Error("Upload failed");
  return response.json() as Promise<BOQ>;
};

